CREATE TABLE IF NOT EXISTS vx_referral_codes(id TEXT PRIMARY KEY,owner_user_id INTEGER NOT NULL UNIQUE,code TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','paused')),rate_bps INTEGER NOT NULL DEFAULT 2000 CHECK(rate_bps BETWEEN 0 AND 10000),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vx_referral_clicks(id TEXT PRIMARY KEY,code_id TEXT NOT NULL,visitor_key TEXT NOT NULL DEFAULT '',ip_hash TEXT NOT NULL DEFAULT '',landing_path TEXT NOT NULL DEFAULT '/',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(code_id) REFERENCES vx_referral_codes(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_vx_clicks_code_time ON vx_referral_clicks(code_id,created_at DESC);
CREATE TABLE IF NOT EXISTS vx_referral_attributions(id TEXT PRIMARY KEY,code_id TEXT NOT NULL,referred_user_id INTEGER NOT NULL UNIQUE,visitor_key TEXT NOT NULL DEFAULT '',attributed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,FOREIGN KEY(code_id) REFERENCES vx_referral_codes(id),FOREIGN KEY(referred_user_id) REFERENCES users(id) ON DELETE CASCADE);
ALTER TABLE orders ADD COLUMN vx_referral_attribution_id TEXT;
CREATE TABLE IF NOT EXISTS vx_referral_commissions(id TEXT PRIMARY KEY,order_id INTEGER NOT NULL UNIQUE,code_id TEXT NOT NULL,referrer_user_id INTEGER NOT NULL,referred_user_id INTEGER NOT NULL,base_amount INTEGER NOT NULL CHECK(base_amount>=0),rate_bps INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),currency TEXT NOT NULL DEFAULT 'THB',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','payable','processing','paid','void','reversed')),payout_id TEXT,hold_until TEXT NOT NULL,void_reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(code_id) REFERENCES vx_referral_codes(id),FOREIGN KEY(referrer_user_id) REFERENCES users(id),FOREIGN KEY(referred_user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_vx_commissions_owner_status ON vx_referral_commissions(referrer_user_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS vx_referral_payouts(id TEXT PRIMARY KEY,payout_no TEXT NOT NULL UNIQUE,referrer_user_id INTEGER NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'THB',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','processing','paid','failed','cancelled')),proof_key TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT,FOREIGN KEY(referrer_user_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS vx_referral_payout_items(payout_id TEXT NOT NULL,commission_id TEXT NOT NULL UNIQUE,amount INTEGER NOT NULL,PRIMARY KEY(payout_id,commission_id),FOREIGN KEY(payout_id) REFERENCES vx_referral_payouts(id) ON DELETE CASCADE,FOREIGN KEY(commission_id) REFERENCES vx_referral_commissions(id));
CREATE TABLE IF NOT EXISTS vx_referral_adjustments(id TEXT PRIMARY KEY,commission_id TEXT NOT NULL UNIQUE,referrer_user_id INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount<=0),currency TEXT NOT NULL DEFAULT 'THB',reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','settled')),created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,settled_at TEXT,FOREIGN KEY(commission_id) REFERENCES vx_referral_commissions(id),FOREIGN KEY(referrer_user_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id));
